-- Turkey: ES/DE/FR translations for the deep-dive content in
-- migration 301. Same JOIN-based pattern as Vietnam's 292 --
-- lifecycle statuses are disambiguated via both lc.sort_order and
-- ls.sort_order since Turkey, like Vietnam, has two lifecycle cards.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Modelo dual — validación centralizada (e-Fatura) o reporte posterior a la emisión (e-Arşiv), ambos canalizados a través de la Administración Tributaria (GİB)', 'Esta página de análisis refleja la orientación pública de la GİB y las noticias del sector disponibles en agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los importes de los umbrales se indexan a la inflación y cambian anualmente — confirme las cifras actuales directamente con la Administración Tributaria (GİB) o con su proveedor de integración antes de basarse en ellas.', 'El marco de facturación electrónica de Turquía es el más maduro de este seguimiento, a excepción de Corea del Sur: la e-Fatura se volvió obligatoria para los grandes contribuyentes el 1 de abril de 2014, apoyándose en los trabajos de transformación digital que la Administración Tributaria (GİB) venía realizando desde 2012. El e-Defter (libros contables electrónicos) siguió en 2015, el e-İrsaliye (albaranes electrónicos) en 2023, y el mandato sigue endureciéndose en 2026 con un umbral general más bajo y la eliminación total del umbral mínimo de la e-Arşiv.', 'Las facturas se elaboran en XML estructurado en formato UBL-TR y se firman digitalmente. Cuál de los dos sistemas electrónicos paralelos de Turquía se aplica — e-Fatura o e-Arşiv — depende de si el propio destinatario está registrado en e-Fatura, no de la elección del vendedor.', 'El mandato de Turquía se basa en umbrales de facturación en lugar de ser universal, pero los umbrales han ido bajando de forma constante desde 2014 y varios sectores están obligados con independencia de su tamaño.', 'Cumplir implica comprobar su facturación frente a los umbrales actuales de e-Fatura y e-İrsaliye, confirmar que toda factura por debajo de esos umbrales se sigue emitiendo como factura e-Arşiv, y elegir una vía de acceso — el propio portal de la GİB, un integrador privado (özel entegratör) o una integración directa interna.', 'Turquía exige el cumplimiento de la facturación electrónica mediante las multas por irregularidad especial de la Ley de Procedimiento Tributario (Vergi Usul Kanunu), calculadas como un porcentaje del valor de la factura con un mínimo indexado a la inflación — aplicadas tanto al emisor como, de forma inusual entre los países de este seguimiento, al destinatario que acepta una factura no conforme.', 'El mandato de e-Fatura de Turquía está en vigor desde el 1 de abril de 2014, uno de los regímenes de facturación electrónica más antiguos que cubre este seguimiento, y sigue endureciéndose: el e-İrsaliye (albarán electrónico) se incorporó al marco en 2023, y desde enero de 2026 se eliminó por completo el umbral mínimo de la e-Arşiv, junto con un umbral general de e-Fatura más bajo.', '🇹🇷' FROM countries WHERE name_en = 'Turkey';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Duales Modell — zentrale Freigabe (e-Fatura) oder nachträgliche Meldung (e-Arşiv), beide über die Steuerbehörde (GİB) geleitet', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der GİB und Branchenberichte mit Stand August 2026 wider und dient der allgemeinen Information, nicht der Rechts- oder Steuerberatung. Die Schwellenwerte sind inflationsindexiert und ändern sich jährlich — bestätigen Sie aktuelle Zahlen direkt bei der Steuerbehörde (GİB) oder Ihrem Integrationsanbieter, bevor Sie sich darauf verlassen.', 'Türkiyes E-Invoicing-Rahmen ist der ausgereifteste in diesem Tracker außerhalb Südkoreas: e-Fatura wurde am 1. April 2014 für größere Steuerpflichtige verpflichtend und baute auf den E-Transformations-Grundlagen auf, die die Steuerbehörde (GİB) seit 2012 gelegt hatte. e-Defter (elektronische Bücher) folgte 2015, e-İrsaliye (elektronische Lieferscheine) 2023, und die Pflicht verschärft sich 2026 weiter mit einem niedrigeren allgemeinen Schwellenwert und der vollständigen Abschaffung der Wertgrenze bei e-Arşiv.', 'Rechnungen werden als strukturiertes XML im UBL-TR-Format erstellt und digital signiert. Welches der beiden parallelen türkischen E-Dokumentsysteme gilt — e-Fatura oder e-Arşiv — hängt davon ab, ob der Empfänger selbst bei e-Fatura registriert ist, nicht von der Wahl des Verkäufers.', 'Türkiyes Pflicht basiert auf Umsatzschwellen statt universell zu gelten, doch die Schwellenwerte sind seit 2014 stetig gesunken, und mehrere Branchen sind unabhängig von ihrer Größe erfasst.', 'Um konform zu sein, müssen Sie Ihren Umsatz mit den aktuellen e-Fatura- und e-İrsaliye-Schwellenwerten abgleichen, sicherstellen, dass jede Rechnung unterhalb dieser Schwellenwerte weiterhin als e-Arşiv-Rechnung ausgestellt wird, und einen Zugangsweg wählen — das eigene Portal der GİB, einen privaten Integrator (özel entegratör) oder eine direkte interne Integration.', 'Türkiye setzt die Einhaltung der E-Invoicing-Pflicht über die besonderen Ordnungswidrigkeitsstrafen des Steuerverfahrensgesetzes (Vergi Usul Kanunu) durch, berechnet als Prozentsatz des Rechnungswerts mit einem inflationsindexierten Mindestbetrag — angewendet sowohl auf den Aussteller als auch, ungewöhnlich unter den Ländern dieses Trackers, auf den Empfänger, der eine nicht konforme Rechnung akzeptiert.', 'Türkiyes e-Fatura-Pflicht gilt seit dem 1. April 2014 und ist damit eines der am längsten bestehenden E-Invoicing-Regime, die dieser Tracker erfasst, und verschärft sich weiter: e-İrsaliye (e-Waybill) kam 2023 zum Rahmen hinzu, und ab Januar 2026 wurde die Wertgrenze bei e-Arşiv vollständig abgeschafft, zusammen mit einem niedrigeren allgemeinen e-Fatura-Schwellenwert.', '🇹🇷' FROM countries WHERE name_en = 'Turkey';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Modèle double — validation centralisée (e-Fatura) ou déclaration après émission (e-Arşiv), toutes deux acheminées via l''Administration fiscale (GİB)', 'Cette page d''analyse reflète les indications publiques de la GİB et les informations sectorielles disponibles en août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les montants des seuils sont indexés sur l''inflation et changent chaque année — confirmez les chiffres actuels directement auprès de l''Administration fiscale (GİB) ou de votre prestataire d''intégration avant de vous y fier.', 'Le cadre de facturation électronique de la Turquie est le plus mature de ce suivi après celui de la Corée du Sud : l''e-Fatura est devenue obligatoire pour les plus grands contribuables le 1er avril 2014, s''appuyant sur les travaux de transformation numérique que l''Administration fiscale (GİB) menait depuis 2012. L''e-Defter (livres comptables électroniques) a suivi en 2015, l''e-İrsaliye (bons de livraison électroniques) en 2023, et l''obligation continue de se durcir en 2026 avec un seuil général plus bas et la suppression totale du seuil minimal de l''e-Arşiv.', 'Les factures sont établies en XML structuré au format UBL-TR et signées électroniquement. Lequel des deux systèmes électroniques parallèles de la Turquie s''applique — e-Fatura ou e-Arşiv — dépend du fait que le destinataire soit lui-même enregistré à l''e-Fatura, et non du choix du vendeur.', 'L''obligation turque repose sur des seuils de chiffre d''affaires plutôt que d''être universelle, mais ces seuils ont régulièrement baissé depuis 2014 et plusieurs secteurs sont concernés quelle que soit leur taille.', 'Se mettre en conformité suppose de comparer votre chiffre d''affaires aux seuils actuels de l''e-Fatura et de l''e-İrsaliye, de vérifier que chaque facture en dessous de ces seuils est toujours émise en e-Arşiv, et de choisir une voie d''accès — le portail propre de la GİB, un intégrateur privé (özel entegratör), ou une intégration interne directe.', 'La Turquie fait respecter la conformité de la facturation électronique par les amendes pour irrégularité spéciale de la loi de procédure fiscale (Vergi Usul Kanunu), calculées en pourcentage de la valeur de la facture avec un minimum indexé sur l''inflation — appliquées à la fois à l''émetteur et, fait inhabituel parmi les pays de ce suivi, au destinataire qui accepte une facture non conforme.', 'L''obligation d''e-Fatura de la Turquie est en vigueur depuis le 1er avril 2014, l''un des régimes de facturation électronique les plus anciens couverts par ce suivi, et continue de se durcir : l''e-İrsaliye (bon de livraison électronique) a rejoint le dispositif en 2023, et depuis janvier 2026 le seuil minimal de l''e-Arşiv a été totalement supprimé, aux côtés d''un seuil général d''e-Fatura plus bas.', '🇹🇷' FROM countries WHERE name_en = 'Turkey';

