INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato de elaboración", "XML estructurado (UBL-TR), firmado digitalmente"], ["Elemento de verificación", "Registro de validación de la GİB (e-Fatura) o un informe a la GİB el mismo día (e-Arşiv)"], ["Base legal", "Comunicados generales de la Ley de Procedimiento Tributario (Vergi Usul Kanunu) sobre e-Fatura, e-Arşiv, e-Defter y e-İrsaliye"], ["Vías de acceso", "El propio portal e-Belge de la GİB, un integrador privado (özel entegratör), o una integración directa interna"]]', 'Toda factura tiene el mismo formato XML subyacente, sea cual sea la vía — la e-Fatura y la e-Arşiv se diferencian en quién es el destinatario y en cómo la GİB ve los datos, no en la estructura del propio documento.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Erstellungsformat", "Strukturiertes XML (UBL-TR), digital signiert"], ["Prüfnachweis", "GİB-Freigabevermerk (e-Fatura) oder eine tagesgleiche GİB-Meldung (e-Arşiv)"], ["Rechtsgrundlage", "Allgemeine Kommuniqués des Steuerverfahrensgesetzes (Vergi Usul Kanunu) zu e-Fatura, e-Arşiv, e-Defter und e-İrsaliye"], ["Zugangswege", "Das eigene e-Belge-Portal der GİB, ein privater Integrator (özel entegratör), oder eine direkte interne Integration"]]', 'Jede Rechnung hat unabhängig vom gewählten Weg dasselbe zugrunde liegende XML-Format — e-Fatura und e-Arşiv unterscheiden sich darin, wer der Empfänger ist und wie die GİB die Daten sieht, nicht in der Struktur des Dokuments selbst.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format de rédaction", "XML structuré (UBL-TR), signé électroniquement"], ["Élément de vérification", "Enregistrement de validation de la GİB (e-Fatura) ou un rapport à la GİB le jour même (e-Arşiv)"], ["Base légale", "Communiqués généraux de la loi de procédure fiscale (Vergi Usul Kanunu) relatifs à l''e-Fatura, l''e-Arşiv, l''e-Defter et l''e-İrsaliye"], ["Voies d''accès", "Le portail e-Belge propre de la GİB, un intégrateur privé (özel entegratör), ou une intégration interne directe"]]', 'Chaque facture partage le même format XML sous-jacent, quelle que soit la voie utilisée — l''e-Fatura et l''e-Arşiv se différencient par l''identité du destinataire et la façon dont la GİB voit les données, pas par la structure du document lui-même.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identidad del contribuyente", "Número de identificación fiscal turco (VKN), o número de identidad nacional (TCKN) para personas físicas"], ["Registro en e-Fatura", "Obligatorio al superar el umbral vigente, o si pertenece a un sector siempre obligado"], ["Registro en e-İrsaliye", "Obligatorio por separado al superar su propio umbral, más alto"], ["Proveedores extranjeros", "Los proveedores de servicios digitales no residentes se registran a efectos del IVA, pero generalmente emiten e-Arşiv en lugar de e-Fatura a los consumidores finales"]]', 'El registro en e-Fatura y en e-İrsaliye se controla frente a dos umbrales distintos — superar uno no implica automáticamente haber superado el otro.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-Identität", "Türkische Steuernummer (VKN), oder nationale Identitätsnummer (TCKN) für Privatpersonen"], ["e-Fatura-Registrierung", "Erforderlich, sobald der aktuelle Schwellenwert überschritten wird, oder bei Zugehörigkeit zu einer stets verpflichteten Branche"], ["e-İrsaliye-Registrierung", "Separat erforderlich, sobald der eigene, höhere Schwellenwert überschritten wird"], ["Ausländische Anbieter", "Gebietsfremde Anbieter digitaler Dienste registrieren sich für die Umsatzsteuer, stellen Endverbrauchern aber in der Regel e-Arşiv statt e-Fatura aus"]]', 'e-Fatura- und e-İrsaliye-Registrierung werden anhand zweier unterschiedlicher Schwellenwerte geprüft — das Überschreiten des einen bedeutet nicht automatisch, dass auch der andere überschritten wurde.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants & inscription', '[["Identité du contribuable", "Numéro d''identification fiscale turc (VKN), ou numéro d''identité national (TCKN) pour les particuliers"], ["Inscription à l''e-Fatura", "Requise dès le franchissement du seuil en vigueur, ou en cas d''appartenance à un secteur toujours soumis à l''obligation"], ["Inscription à l''e-İrsaliye", "Requise séparément dès le franchissement de son propre seuil, plus élevé"], ["Fournisseurs étrangers", "Les fournisseurs de services numériques non-résidents s''inscrivent à la TVA mais émettent généralement des factures e-Arşiv plutôt que e-Fatura aux consommateurs finaux"]]', 'L''inscription à l''e-Fatura et à l''e-İrsaliye est suivie par rapport à deux seuils différents — franchir l''un ne signifie pas automatiquement avoir franchi l''autre.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio y archivo', '[["Datos de las partes", "Números de identificación fiscal del vendedor y del comprador (VKN/TCKN)"], ["Tipos de factura", "e-Fatura (validada, destinatarios registrados) o e-Arşiv (el resto, incluidos los consumidores)"], ["Período de conservación", "10 años, junto con el resto de registros contables conforme a la Ley de Procedimiento Tributario"], ["e-Defter", "Presentación del libro mayor/diario electrónico obligatoria para todo usuario de e-Fatura"]]', 'El período de conservación de diez años coincide con la obligación contable general de la Ley de Procedimiento Tributario turca, no es una norma exclusiva de la facturación electrónica.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte & Archivierung', '[["Parteidaten", "Steuernummern von Verkäufer und Käufer (VKN/TCKN)"], ["Rechnungsarten", "e-Fatura (freigegeben, registrierte Empfänger) oder e-Arşiv (alle anderen, einschließlich Verbraucher)"], ["Aufbewahrungsfrist", "10 Jahre, wie alle übrigen Buchführungsunterlagen nach dem Steuerverfahrensgesetz"], ["e-Defter", "Elektronische Haupt-/Journalbuchführung für jeden e-Fatura-Nutzer verpflichtend"]]', 'Die zehnjährige Aufbewahrungsfrist entspricht der allgemeinen Buchführungspflicht des türkischen Steuerverfahrensgesetzes, keiner speziell für E-Invoicing geltenden Regel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire & archivage', '[["Données des parties", "Numéros d''identification fiscale du vendeur et de l''acheteur (VKN/TCKN)"], ["Types de facture", "e-Fatura (validée, destinataires enregistrés) ou e-Arşiv (tous les autres, y compris les consommateurs)"], ["Durée de conservation", "10 ans, comme tous les autres documents comptables au titre de la loi de procédure fiscale"], ["e-Defter", "Dépôt du grand livre/journal électronique obligatoire pour tout utilisateur de l''e-Fatura"]]', 'La durée de conservation de dix ans correspond à l''obligation comptable générale de la loi de procédure fiscale turque, et non à une règle propre à la facturation électronique.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'e-Fatura — validación centralizada (destinatarios registrados)', 'Cuando ambas partes son usuarios registrados de e-Fatura, la factura sigue esta secuencia:', 'El vendedor y el comprador nunca intercambian la factura directamente — la GİB se sitúa en medio de toda e-Fatura, un auténtico modelo de validación (clearance), la misma forma que Jordania e Israel en otros puntos de este seguimiento, aunque centralizado en una única plataforma gubernamental en lugar de un intercambio descentralizado.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'e-Fatura — zentrale Freigabe (registrierte Empfänger)', 'Wenn beide Parteien registrierte e-Fatura-Nutzer sind, folgt eine Rechnung diesem Ablauf:', 'Verkäufer und Käufer tauschen die Rechnung nie direkt aus — die GİB steht bei jeder e-Fatura in der Mitte, ein echtes Freigabemodell (Clearance), dieselbe Form wie bei Jordanien und Israel an anderer Stelle in diesem Tracker, wenngleich über eine einzige staatliche Plattform zentralisiert statt über einen dezentralen Austausch.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'e-Fatura — validation centralisée (destinataires enregistrés)', 'Lorsque les deux parties sont des utilisateurs enregistrés de l''e-Fatura, une facture suit cette séquence :', 'Le vendeur et l''acheteur n''échangent jamais directement la facture — la GİB se situe au milieu de chaque e-Fatura, un véritable modèle de validation (clearance), de la même forme que la Jordanie et Israël ailleurs dans ce suivi, bien que centralisé via une plateforme gouvernementale unique plutôt qu''un échange décentralisé.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0;

