INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Transmise à la plateforme centrale de la GİB' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'La GİB valida y libera la factura' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die GİB prüft und gibt die Rechnung frei' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'La GİB valide et libère la facture' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'La factura validada se distribuye al comprador registrado' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die freigegebene Rechnung wird an den registrierten Käufer verteilt' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'La facture validée est distribuée à l''acheteur enregistré' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 0 AND ls.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'e-Arşiv — reporte posterior a la emisión (el resto)', 'Cuando el destinatario no está registrado en e-Fatura — la mayoría de los consumidores y muchas empresas más pequeñas —, la factura sigue en cambio esta secuencia:', 'Este es el flujo más parecido al modelo posterior a la emisión de Corea del Sur en otro punto de este seguimiento — la factura es válida en el momento de la entrega, y el reporte a la GİB es una obligación paralela, no un requisito previo para su validez. Desde enero de 2026 no existe un valor mínimo de factura por debajo del cual la e-Arşiv pueda volver al papel.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'e-Arşiv — nachträgliche Meldung (alle anderen)', 'Wenn der Empfänger nicht bei e-Fatura registriert ist — die meisten Verbraucher und viele kleinere Unternehmen —, folgt die Rechnung stattdessen diesem Ablauf:', 'Dies ist der Ablauf, der dem Modell Südkoreas nach der Ausstellung an anderer Stelle in diesem Tracker am ähnlichsten ist — die Rechnung ist bei Zustellung gültig, und die Meldung an die GİB ist eine parallele Pflicht, keine Voraussetzung für die Gültigkeit. Seit Januar 2026 gibt es keinen Mindestrechnungswert mehr, unterhalb dessen e-Arşiv auf Papier zurückfallen kann.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'e-Arşiv — déclaration après émission (tous les autres)', 'Lorsque le destinataire n''est pas enregistré à l''e-Fatura — la plupart des consommateurs, et de nombreuses petites entreprises —, la facture suit à la place cette séquence :', 'C''est le flux le plus proche du modèle après émission de la Corée du Sud ailleurs dans ce suivi — la facture est valide dès sa remise, et la déclaration à la GİB est une obligation parallèle, non une condition préalable à sa validité. Depuis janvier 2026, il n''existe plus de valeur minimale de facture en dessous de laquelle l''e-Arşiv peut revenir au papier.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1;

