INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Los datos de la factura se reportan a la GİB, generalmente el mismo día' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Rechnungsdaten werden der GİB gemeldet, in der Regel am selben Tag' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Les données de la facture sont déclarées à la GİB, généralement le jour même' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'La GİB conserva los datos reportados para sus propios registros' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die GİB speichert die gemeldeten Daten für ihre eigenen Unterlagen' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'La GİB conserve les données déclarées pour ses propres archives' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Turkey' AND lc.sort_order = 1 AND ls.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Quién está obligado, y desde cuándo', '[["Facturación superior a 5 millones de TRY (umbral de lanzamiento de 2014)", "e-Fatura obligatoria desde el 1 de abril de 2014"], ["Facturación superior a 3 millones de TRY (umbral general de 2026, sobre ingresos de 2025)", "e-Fatura obligatoria; regístrese antes del 1 de julio de 2026"], ["Comercio electrónico, inmobiliario, vehículos a motor, alojamiento con licencia", "Se aplica el umbral inferior de 500.000 TRY para e-Fatura"], ["Energía, mayoristas de frutas/verduras, mercados en línea, importadores", "e-Fatura obligatoria con independencia de la facturación"], ["Facturación superior a 10 millones de TRY", "e-İrsaliye (albarán electrónico) obligatorio desde el 1 de julio de 2023, controlado por separado"]]', 'El umbral de e-Fatura ha caído de 5 millones de TRY en su lanzamiento a tan solo 500.000 TRY para sectores específicos en 2026 — un endurecimiento constante en lugar de un único cambio brusco, de forma similar al propio historial de umbrales de Corea del Sur.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Wer ist erfasst, und seit wann', '[["Umsatz über 5 Millionen TRY (Einführungsschwelle 2014)", "e-Fatura verpflichtend seit 1. April 2014"], ["Umsatz über 3 Millionen TRY (allgemeine Schwelle 2026, bezogen auf Umsatz 2025)", "e-Fatura verpflichtend; Registrierung bis 1. Juli 2026"], ["E-Commerce, Immobilien, Kraftfahrzeuge, lizenzierte Beherbergung", "Niedrigere e-Fatura-Schwelle von 500.000 TRY gilt"], ["Energie, Obst-/Gemüsegroßhandel, Online-Marktplätze, Importeure", "e-Fatura verpflichtend unabhängig vom Umsatz"], ["Umsatz über 10 Millionen TRY", "e-İrsaliye (elektronischer Lieferschein) verpflichtend seit 1. Juli 2023, separat erfasst"]]', 'Die e-Fatura-Schwelle ist von 5 Millionen TRY bei der Einführung auf bis zu 500.000 TRY für bestimmte Branchen im Jahr 2026 gesunken — eine stetige Verschärfung statt eines einmaligen Umbruchs, ähnlich dem eigenen Schwellenverlauf Südkoreas.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Qui est concerné, et depuis quand', '[["Chiffre d''affaires supérieur à 5 millions de TRY (seuil de lancement de 2014)", "e-Fatura obligatoire depuis le 1er avril 2014"], ["Chiffre d''affaires supérieur à 3 millions de TRY (seuil général 2026, sur les revenus 2025)", "e-Fatura obligatoire ; inscription avant le 1er juillet 2026"], ["Commerce électronique, immobilier, véhicules à moteur, hébergement agréé", "Le seuil e-Fatura inférieur de 500 000 TRY s''applique"], ["Énergie, grossistes en fruits/légumes, places de marché en ligne, importateurs", "e-Fatura obligatoire quel que soit le chiffre d''affaires"], ["Chiffre d''affaires supérieur à 10 millions de TRY", "e-İrsaliye (bon de livraison électronique) obligatoire depuis le 1er juillet 2023, suivi séparément"]]', 'Le seuil de l''e-Fatura est passé de 5 millions de TRY lors du lancement à seulement 500 000 TRY pour certains secteurs en 2026 — un durcissement progressif plutôt qu''un basculement unique, une trajectoire proche de celle des seuils sud-coréens.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Qué está cubierto', '[["B2B nacional (destinatarios registrados)", "e-Fatura"], ["B2B/B2C nacional (destinatarios no registrados)", "e-Arşiv, obligatoria con independencia del importe desde enero de 2026"], ["B2G", "e-Fatura, cuando el propio organismo público está registrado en e-Fatura"], ["Movimiento/despacho de mercancías", "e-İrsaliye, controlado por separado de la propia factura"], ["Exportaciones", "Se aplica la documentación aduanera estándar; no constituye en sí un requisito de e-Fatura"]]', 'Entre la e-Fatura y la e-Arşiv, prácticamente toda venta nacional queda cubierta electrónicamente de alguna forma — la pregunta abierta para una operación concreta es cuál de los dos sistemas se aplica, no si alguno de ellos lo hace.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was ist abgedeckt', '[["Inländisches B2B (registrierte Empfänger)", "e-Fatura"], ["Inländisches B2B/B2C (nicht registrierte Empfänger)", "e-Arşiv, verpflichtend unabhängig vom Wert seit Januar 2026"], ["B2G", "e-Fatura, sofern die Behörde selbst bei e-Fatura registriert ist"], ["Warenbewegung/Versand", "e-İrsaliye, getrennt von der Rechnung selbst erfasst"], ["Exporte", "Es gelten die üblichen Zolldokumente; keine eigene e-Fatura-Pflicht"]]', 'Zwischen e-Fatura und e-Arşiv ist praktisch jeder inländische Verkauf in irgendeiner Form elektronisch erfasst — die offene Frage bei einer konkreten Transaktion ist, welches der beiden Systeme gilt, nicht ob eines von beiden gilt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est couvert', '[["B2B domestique (destinataires enregistrés)", "e-Fatura"], ["B2B/B2C domestique (destinataires non enregistrés)", "e-Arşiv, obligatoire quel que soit le montant depuis janvier 2026"], ["B2G", "e-Fatura, lorsque l''organisme public est lui-même enregistré à l''e-Fatura"], ["Mouvement/expédition de marchandises", "e-İrsaliye, suivi séparément de la facture elle-même"], ["Exportations", "La documentation douanière standard s''applique ; ne constitue pas en soi une exigence e-Fatura"]]', 'Entre l''e-Fatura et l''e-Arşiv, pratiquement toute vente domestique est couverte électroniquement sous une forme ou une autre — la question ouverte pour une transaction donnée est de savoir lequel des deux systèmes s''applique, non si l''un d''eux s''applique.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

