INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Défaut d''émission d''une facture électronique requise (émetteur)', '10 % de la valeur de la facture, minimum 2 200 TRY', NULL FROM deep_dive_penalty_rows pr JOIN countries c ON c.id = pr.country_id WHERE c.name_en = 'Turkey' AND pr.sort_order = 0;
