INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Annahme/Verbuchung einer nicht konformen Rechnung (Empfänger)', '10 % des Rechnungswerts, mindestens 2.200 TRY', NULL FROM deep_dive_penalty_rows pr JOIN countries c ON c.id = pr.country_id WHERE c.name_en = 'Turkey' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Acceptation/enregistrement d''une facture non conforme (destinataire)', '10 % de la valeur de la facture, minimum 2 200 TRY', NULL FROM deep_dive_penalty_rows pr JOIN countries c ON c.id = pr.country_id WHERE c.name_en = 'Turkey' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Ambas partes de la operación están expuestas', NULL, NULL, 'A diferencia de la mayoría de los países de este seguimiento, la multa por irregularidad especial de Turquía (Ley de Procedimiento Tributario, Mükerrer Madde 355) se aplica tanto al emisor que no emite una factura electrónica obligatoria como al destinatario que acepta o registra a sabiendas una factura no conforme — una estructura de doble responsabilidad que presiona a ambas partes para que acierten con el tipo de documento, no solo al vendedor.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Beide Seiten der Transaktion sind haftbar', NULL, NULL, 'Anders als in den meisten Ländern dieses Trackers gilt Türkiyes besondere Ordnungswidrigkeitsstrafe (Steuerverfahrensgesetz, Mükerrer Madde 355) sowohl für den Aussteller, der eine erforderliche E-Rechnung nicht ausstellt, als auch für den Empfänger, der eine nicht konforme Rechnung wissentlich annimmt oder verbucht — eine doppelte Verantwortungsstruktur, die beide Parteien unter Druck setzt, den richtigen Dokumenttyp zu verwenden, nicht nur den Verkäufer.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Les deux parties à la transaction sont exposées', NULL, NULL, 'Contrairement à la plupart des pays de ce suivi, l''amende pour irrégularité spéciale de la Turquie (loi de procédure fiscale, Mükerrer Madde 355) s''applique à la fois à l''émetteur qui n''émet pas une facture électronique requise et au destinataire qui accepte ou enregistre sciemment une facture non conforme — une structure de double responsabilité qui incite les deux parties à choisir le bon type de document, pas seulement le vendeur.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📈 Una multa porcentual, no una tarifa fija', NULL, NULL, 'La estructura del 10% del valor de la factura hace que la multa se ajuste automáticamente al tamaño de la operación, con un mínimo fijo (2.200 TRY, ajustado periódicamente por inflación) como suelo para las facturas de bajo valor — una forma claramente distinta de la escala por número de infracciones de Vietnam o de la multa fija en JOD de Jordania en otros puntos de este seguimiento.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📈 Eine prozentuale Strafe, keine Pauschale', NULL, NULL, 'Die Struktur von 10 % des Rechnungswerts sorgt dafür, dass sich die Strafe automatisch an die Transaktionsgröße anpasst, mit einem festen Mindestbetrag (2.200 TRY, periodisch inflationsangepasst) als Untergrenze für niedrigwertige Rechnungen — eine deutlich andere Form als Vietnams Staffelung nach Verstoßzahl oder Jordaniens feste JOD-Strafe an anderer Stelle in diesem Tracker.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📈 Une amende proportionnelle, pas un montant fixe', NULL, NULL, 'La structure de 10 % de la valeur de la facture fait que l''amende s''ajuste automatiquement à la taille de la transaction, avec un minimum fixe (2 200 TRY, ajusté périodiquement pour l''inflation) comme plancher pour les factures de faible valeur — une forme très différente de l''échelonnement par nombre d''infractions du Viêt Nam ou de l''amende fixe en JOD de la Jordanie ailleurs dans ce suivi.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📅 El reporte tardío de e-Arşiv y e-Defter conlleva sus propias multas', NULL, NULL, 'Más allá de la sanción por falta de emisión indicada arriba, el reporte tardío de e-Arşiv o la presentación tardía de e-Defter (libro contable electrónico) conllevan cada uno multas adicionales dentro del mismo marco general de sanciones por irregularidad — las fuentes públicas disponibles no coinciden en una cifra actual única para estos casos, por lo que debe considerar que la tabla de sanciones de esta página cubre únicamente la falta de emisión, y confirmar las multas por presentación tardía directamente con la GİB o con su proveedor de integración antes de basarse en una cifra concreta.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📅 Verspätete e-Arşiv- und e-Defter-Meldungen ziehen eigene Strafen nach sich', NULL, NULL, 'Über die oben genannte Strafe für Nichtausstellung hinaus lösen sowohl eine verspätete e-Arşiv-Meldung als auch eine verspätete e-Defter-Einreichung (elektronisches Hauptbuch) jeweils zusätzliche Strafen im Rahmen desselben allgemeinen Ordnungswidrigkeitsrahmens aus — öffentlich verfügbare Quellen stimmen bei einer einzigen aktuellen Zahl hierfür nicht überein. Betrachten Sie die Strafentabelle dieser Seite daher als auf die Nichtausstellung beschränkt, und bestätigen Sie Strafen für verspätete Einreichungen direkt bei der GİB oder Ihrem Integrationsanbieter, bevor Sie sich auf eine bestimmte Zahl verlassen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📅 Les déclarations tardives e-Arşiv et e-Defter entraînent leurs propres amendes', NULL, NULL, 'Au-delà de la pénalité de non-émission ci-dessus, une déclaration e-Arşiv tardive ou un dépôt e-Defter (grand livre électronique) tardif entraînent chacun des amendes supplémentaires dans le cadre du même régime général de sanctions pour irrégularité — les sources publiques disponibles ne convergent pas vers un chiffre actuel unique pour ces cas, aussi convient-il de considérer que le tableau des sanctions de cette page ne couvre que la non-émission, et de confirmer les amendes pour dépôt tardif directement auprès de la GİB ou de votre prestataire d''intégration avant de vous fier à un chiffre précis.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Turkey' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Compruebe su facturación de 2025 frente a los umbrales de e-Fatura de 2026', 'Compare su facturación de 2025 con el umbral general de 3 millones de TRY, o con el umbral de 500.000 TRY si opera en comercio electrónico, inmobiliario, vehículos a motor o alojamiento con licencia — y regístrese en e-Fatura antes del 1 de julio de 2026 si lo supera.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie Ihren Umsatz 2025 anhand der e-Fatura-Schwellenwerte 2026', 'Vergleichen Sie Ihren Umsatz 2025 mit der allgemeinen Schwelle von 3 Millionen TRY oder der Schwelle von 500.000 TRY, wenn Sie im E-Commerce, in der Immobilienbranche, im Kraftfahrzeugbereich oder in lizenzierten Beherbergungsbetrieben tätig sind — und registrieren Sie sich bis zum 1. Juli 2026 für e-Fatura, falls Sie die Schwelle überschreiten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez votre chiffre d''affaires 2025 par rapport aux seuils e-Fatura de 2026', 'Comparez votre chiffre d''affaires 2025 au seuil général de 3 millions de TRY, ou au seuil de 500 000 TRY si vous exercez dans le commerce électronique, l''immobilier, les véhicules à moteur ou l''hébergement agréé — et inscrivez-vous à l''e-Fatura avant le 1er juillet 2026 si vous le franchissez.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que toda factura a un destinatario no registrado se emite como e-Arşiv', 'Desde enero de 2026 no existe un valor mínimo por debajo del cual una factura en papel sea aceptable para un destinatario no registrado en e-Fatura — confirme que su sistema de facturación emite la e-Arşiv de forma electrónica para toda operación de este tipo, no solo para las de mayor importe.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Stellen Sie sicher, dass jede Rechnung an einen nicht registrierten Empfänger als e-Arşiv ausgestellt wird', 'Seit Januar 2026 gibt es keinen Mindestwert mehr, unterhalb dessen eine Papierrechnung für einen nicht bei e-Fatura registrierten Empfänger akzeptabel ist — stellen Sie sicher, dass Ihr Rechnungssystem für jeden solchen Verkauf elektronisch eine e-Arşiv ausstellt, nicht nur für größere.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez que chaque facture à un destinataire non enregistré est émise en e-Arşiv', 'Depuis janvier 2026, il n''existe plus de valeur minimale en dessous de laquelle une facture papier est acceptable pour un destinataire non enregistré à l''e-Fatura — vérifiez que votre système de facturation émet l''e-Arşiv électroniquement pour chaque vente de ce type, pas seulement pour les plus importantes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Compruebe el umbral de e-İrsaliye por separado', 'Si su facturación supera los 10 millones de TRY y despacha mercancías físicas, confirme que la emisión de e-İrsaliye está integrada junto a su facturación — se controla frente a su propio umbral, no frente al de la e-Fatura.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die e-İrsaliye-Schwelle separat', 'Wenn Ihr Umsatz 10 Millionen TRY übersteigt und Sie physische Waren versenden, stellen Sie sicher, dass die e-İrsaliye-Ausstellung zusätzlich zu Ihrer Rechnungsstellung integriert ist — sie wird anhand ihrer eigenen Schwelle geprüft, nicht der von e-Fatura.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez le seuil de l''e-İrsaliye séparément', 'Si votre chiffre d''affaires dépasse 10 millions de TRY et que vous expédiez des marchandises physiques, vérifiez que l''émission de l''e-İrsaliye est intégrée à votre facturation — elle est suivie par rapport à son propre seuil, pas celui de l''e-Fatura.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija una vía de acceso', 'Decida entre el propio portal e-Belge gratuito de la GİB (adecuado para volúmenes de facturación más bajos), un integrador privado (özel entegratör) que ofrece herramientas adicionales, o una integración directa interna para emisores de mayor volumen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen Zugangsweg', 'Entscheiden Sie sich zwischen dem eigenen kostenlosen e-Belge-Portal der GİB (geeignet für geringere Rechnungsvolumina), einem privaten Integrator (özel entegratör) mit zusätzlichen Werkzeugen, oder einer direkten internen Integration für Aussteller mit höherem Volumen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez une voie d''accès', 'Choisissez entre le portail e-Belge gratuit de la GİB (adapté aux volumes de facturation plus faibles), un intégrateur privé (özel entegratör) proposant des outils supplémentaires, ou une intégration interne directe pour les émetteurs à plus fort volume.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que las declaraciones de e-Defter están al día', 'Todo usuario de e-Fatura, y toda empresa sujeta a auditoría independiente conforme a los umbrales del Código de Comercio turco, debe presentar también el e-Defter (libros contables electrónicos) — confirme que está integrado junto a su facturación, y no tratado como un paso aparte y opcional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Stellen Sie sicher, dass die e-Defter-Einreichungen aktuell sind', 'Jeder e-Fatura-Nutzer sowie jedes Unternehmen, das nach den Schwellenwerten des türkischen Handelsgesetzbuchs einer unabhängigen Prüfung unterliegt, muss auch e-Defter (elektronische Bücher) einreichen — stellen Sie sicher, dass dies neben Ihrer Rechnungsstellung integriert ist und nicht als separater, optionaler Schritt behandelt wird.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez que les dépôts e-Defter sont à jour', 'Tout utilisateur de l''e-Fatura, ainsi que toute entreprise soumise à un audit indépendant selon les seuils du Code de commerce turc, doit également déposer l''e-Defter (livres comptables électroniques) — vérifiez que cela est intégré à votre facturation, et non traité comme une étape distincte et facultative.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Conserve todo documento electrónico durante 10 años', 'Los registros de e-Fatura, e-Arşiv, e-Defter y e-İrsaliye están todos sujetos a la obligación general de conservación de 10 años de la Ley de Procedimiento Tributario — conserve los archivos electrónicos firmados originales, no solo una representación en PDF.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bewahren Sie jedes E-Dokument 10 Jahre lang auf', 'e-Fatura-, e-Arşiv-, e-Defter- und e-İrsaliye-Unterlagen unterliegen alle der allgemeinen 10-jährigen Aufbewahrungspflicht des Steuerverfahrensgesetzes — bewahren Sie die ursprünglichen signierten elektronischen Dateien auf, nicht nur eine PDF-Darstellung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Conservez chaque document électronique pendant 10 ans', 'Les documents e-Fatura, e-Arşiv, e-Defter et e-İrsaliye relèvent tous de l''obligation générale de conservation de 10 ans de la loi de procédure fiscale — conservez les fichiers électroniques signés d''origine, pas seulement un rendu PDF.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Turkey' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Administración Tributaria (GİB) — portal e-Belge' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Turkey' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Steuerbehörde (GİB) — e-Belge-Portal' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Turkey' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Administration fiscale (GİB) — portail e-Belge' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Turkey' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Administración Tributaria (Gelir İdaresi Başkanlığı, GİB)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Turkey' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Steuerbehörde (Gelir İdaresi Başkanlığı, GİB)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Turkey' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Administration fiscale (Gelir İdaresi Başkanlığı, GİB)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Turkey' AND dp.sort_order = 1;
